async function unlockChunked(){const p=$('#pass').value.trim();if(!p)return;$('#lockmsg').textContent='Decrypting 300 applications…';try{const env=await fetch('manifest.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error('Encrypted manifest not found');return r.json()});if(!Array.isArray(env.parts)||!env.parts.length)throw new Error('Invalid encrypted manifest');const parts=await Promise.all(env.parts.map(name=>fetch(name,{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error(`Missing ${name}`);return r.text()})));const data=parts.join('').trim();const keyMat=await crypto.subtle.importKey('raw',new TextEncoder().encode(p),'PBKDF2',false,['deriveKey']);const key=await crypto.subtle.deriveKey({name:'PBKDF2',salt:b64(env.salt),iterations:env.iterations,hash:'SHA-256'},keyMat,{name:'AES-GCM',length:256},false,['decrypt']);const cipher=b64(data),tag=b64(env.tag),combined=new Uint8Array(cipher.length+tag.length);combined.set(cipher);combined.set(tag,cipher.length);const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:b64(env.iv),tagLength:128},key,combined);const obj=JSON.parse(new TextDecoder().decode(plain));if(!obj||!Array.isArray(obj.applications)||obj.applications.length!==300)throw new Error(`Expected 300 applications, got ${obj?.applications?.length??'invalid'}`);DATA=obj.applications.map(enrich);$('#lock').classList.add('hidden');$('#app').classList.remove('hidden');render()}catch(e){console.error(e);$('#lockmsg').textContent='Wrong passphrase or encrypted dataset unavailable.'}}
$('#unlock').onclick=unlockChunked;$('#pass').onkeydown=e=>{if(e.key==='Enter')unlockChunked()};